import csv, sys, subprocess
rep = sys.argv[1]
ncu = subprocess.run(["ncu","--import",rep,"--csv","--page","raw"],
                     capture_output=True, text=True)
rows = list(csv.reader(ncu.stdout.splitlines()))
# header is the first non-empty row whose first cell is "ID" or similar; find row with "Kernel Name"
hdr = None
for i,r in enumerate(rows):
    if "Kernel Name" in r or any("bank_conflict" in c for c in r):
        hdr = i; break
# ncu raw csv: row 0 = metric *labels*? Actually find the row containing metric ids
# Simpler: the header row is the one whose cells are metric names (contain '__' or 'Name')
for i,r in enumerate(rows[:5]):
    print(f"--- row {i} sample (first 12): {r[:12]}")
# Find columns of interest by substring in the header row (row that has 'Kernel Name')
hi = None
for i,r in enumerate(rows):
    if "Kernel Name" in r:
        hi = i; break
if hi is None:
    print("no header with Kernel Name; dumping first row cells with idx")
    sys.exit(0)
header = rows[hi]
want = ["bank_conflicts_pipe_lsu_mem_shared_op_ld","bank_conflicts_pipe_lsu_mem_shared_op_st",
        "wavefronts_mem_shared_op_ld","wavefronts_mem_shared_op_st","wavefronts_mem_shared.sum",
        "wavefronts_mem_shared.avg.pct","inst_executed_op_shared_ld","inst_executed_op_shared_st",
        "average_data_bytes_per_wavefront_mem_shared","sm__throughput","l1tex__throughput",
        "smsp__throughput","time_duration","Block Size","Grid Size","Kernel Name"]
cols = {}
for w in want:
    for j,h in enumerate(header):
        if w in h:
            cols.setdefault(w, []).append((j,h))
print("\n=== HEADER MATCHES ===")
for w,lst in cols.items():
    for j,h in lst:
        print(f"  col{j}: {h}  [match {w}]")
print("\n=== DATA ROWS ===")
for r in rows[hi+1:]:
    if len(r) < len(header): continue
    out=[]
    for w in want:
        if w in cols:
            j = cols[w][0][0]
            out.append(f"{w.split('.')[0].split('mem_shared')[-1] or w[:18]}={r[j]}")
    print(" | ".join(out))

